#import <Foundation/Foundation.h>
#import <AppKit/AppKit.h>
#import <PDFKit/PDFKit.h>
void saveRep(NSBitmapImageRep *r,NSString *path){[[r representationUsingType:NSBitmapImageFileTypePNG properties:@{}]writeToFile:path atomically:YES];}
int main(int argc,char **argv){@autoreleasepool{NSMutableDictionary *manifest=[NSMutableDictionary dictionary];for(int n=1;n<argc;n++){NSString *key=n==1?@"pm151":@"pt095";NSString *dir=[@"dist/assets/templates/" stringByAppendingString:key];[[NSFileManager defaultManager]createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:nil];PDFDocument *doc=[[PDFDocument alloc]initWithURL:[NSURL fileURLWithPath:@(argv[n])]];[[NSFileManager defaultManager]copyItemAtPath:@(argv[n]) toPath:[dir stringByAppendingPathComponent:@"reference.pdf"] error:nil];NSMutableArray *pages=[NSMutableArray array];for(NSUInteger i=0;i<doc.pageCount;i++){PDFPage *p=[doc pageAtIndex:i];NSRect b=[p boundsForBox:kPDFDisplayBoxMediaBox];NSMutableArray *lines=[NSMutableArray array];for(PDFSelection *sel in [[p selectionForRect:b]selectionsByLine]){NSRect r=[sel boundsForPage:p];[lines addObject:@{@"text":sel.string?:@"",@"x":@(r.origin.x),@"y":@(b.size.height-NSMaxY(r)),@"width":@(r.size.width),@"height":@(r.size.height)}];} [pages addObject:@{@"page":@(i+1),@"width":@(b.size.width),@"height":@(b.size.height),@"lines":lines}];if(i==0){NSImage *img=[p thumbnailOfSize:NSMakeSize(1224,1584) forBox:kPDFDisplayBoxMediaBox];NSBitmapImageRep *r=[[NSBitmapImageRep alloc]initWithData:img.TIFFRepresentation];saveRep(r,[dir stringByAppendingPathComponent:@"original-cover.png"]);CGFloat sx=r.pixelsWide/b.size.width,sy=r.pixelsHigh/b.size.height;for(NSDictionary *l in lines){NSString *t=l[@"text"];if([t containsString:@"PAKORN TECHNICAL"]||[t containsString:@"PARTNERSHIP"])continue;NSColor *color=[NSColor colorWithDeviceRed:1 green:1 blue:1 alpha:1];if([t containsString:@"PM.FP."]){NSUInteger px[8]={0};[r getPixel:px atX:r.pixelsWide-10 y:(NSInteger)([l[@"y"]doubleValue]*sy)];color=[NSColor colorWithDeviceRed:px[0]/255.0 green:px[1]/255.0 blue:px[2]/255.0 alpha:1];}NSInteger x=MAX(0,floor([l[@"x"]doubleValue]*sx)-3),y=MAX(0,floor([l[@"y"]doubleValue]*sy)-3),right=MIN(r.pixelsWide,ceil(([l[@"x"]doubleValue]+[l[@"width"]doubleValue])*sx)+3),bottom=MIN(r.pixelsHigh,ceil(([l[@"y"]doubleValue]+[l[@"height"]doubleValue])*sy)+3);for(NSInteger yy=y;yy<bottom;yy++)for(NSInteger xx=x;xx<right;xx++)[r setColor:color atX:xx y:yy];}saveRep(r,[dir stringByAppendingPathComponent:@"cover-base.png"]);}if(i==8&&n==1){NSImage *im=[p thumbnailOfSize:NSMakeSize(1224,1584) forBox:kPDFDisplayBoxMediaBox];NSBitmapImageRep *r=[[NSBitmapImageRep alloc]initWithData:im.TIFFRepresentation];CGImageRef cg=CGImageCreateWithImageInRect(r.CGImage,CGRectMake(55,20,310,80));NSBitmapImageRep *logo=[[NSBitmapImageRep alloc]initWithCGImage:cg];saveRep(logo,@"dist/assets/templates/pakorn-logo.png");CGImageRelease(cg);}}manifest[key]=@{@"pageCount":@(doc.pageCount),@"pages":pages};}NSData *data=[NSJSONSerialization dataWithJSONObject:manifest options:NSJSONWritingPrettyPrinted error:nil];[data writeToFile:@"dist/assets/templates/source-layout.json" atomically:YES];NSLog(@"Template assets prepared");}return 0;}
